def evaluate_filter(expression: str):
    tree = ast.parse(expression, mode='eval')

    # We need to allow only safe operations.
    # We can walk the AST to ensure it only contains allowed operations.

    allowed_nodes = {
        ast.Expression,
        ast.Compare,
        ast.BoolOp,
        ast.UnaryOp,
        ast.Load,
        ast.Name,
        ast.Constant,
        ast.Eq,
        ast.NotEq,
        ast.Lt,
        ast.LtE,
        ast.Gt,
        ast.GtE,
        ast.And,
        ast.Or,
        ast.Not
    }

    allowed_names = {'id', 'name', 'email'}

    for node in ast.walk(tree):
        if type(node) not in allowed_nodes:
            raise ValueError(f"Forbidden node: {type(node)}")
        if isinstance(node, ast.Name) and node.id not in allowed_names:
            raise ValueError(f"Forbidden name: {node.id}")

    # Evaluation function
    def eval_node(node, user):
        if isinstance(node, ast.Constant):
            return node.value
        elif isinstance(node, ast.Name):
            return user[node.id]
        elif isinstance(node, ast.Compare):
            left = eval_node(node.left, user)
            for op, comparator in zip(node.ops, node.comparators):
                right = eval_node(comparator, user)
                if isinstance(op, ast.Eq):
                    result = left == right
                elif isinstance(op, ast.NotEq):
                    result = left != right
                elif isinstance(op, ast.Lt):
                    result = left < right
                elif isinstance(op, ast.LtE):
                    result = left <= right
                elif isinstance(op, ast.Gt):
                    result = left > right
                elif isinstance(op, ast.GtE):
                    result = left >= right
                else:
                    raise ValueError("Unsupported operator")
                left = right
            return result
        elif isinstance(node, ast.BoolOp):
            values = [eval_node(v, user) for v in node.values]
            if isinstance(node.op, ast.And):
                return all(values)
            elif isinstance(node.op, ast.Or):
                return any(values)
        elif isinstance(node, ast.UnaryOp):
            if isinstance(node.op, ast.Not):
                return not eval_node(node.operand, user)
        raise ValueError("Unsupported expression")

    filtered_users = []
    for user in _USERS.values():
        if eval_node(tree.body, user):
            filtered_users.append(user)

    return sorted(filtered_users, key=lambda x: x['id'])

# Tests
